// Maze BD \u2014 static data: sizes and storage defaults.
// (Maze content itself is generated by js/logic.js from a seed.)
(function (global) {
  'use strict';

  var DATA = {
    app: 'maze-bd',
    version: 1,
    storageKey: 'maze-bd-v1',
    sizes: [
      { id: 'small', rows: 10, cols: 10 },
      { id: 'medium', rows: 15, cols: 15 },
      { id: 'large', rows: 20, cols: 20 }
    ],
    defaultBest: { small: null, medium: null, large: null }
  };

  if (typeof module !== 'undefined' && module.exports) module.exports = DATA;
  else global.MazeData = DATA;
})(typeof window !== 'undefined' ? window : globalThis);
